~~@JamesNK I was running into this today with latest release and it seems that the fix doesn't work if you are include [action] or {action} as part of your route with a route attribute at the controller level.~~

~~This containers no warnings~~ Edit: This **will** show the warnings
```
[Route("api/[controller]")]
[ApiController]
public class MyController : ControllerBase
{
    [HttpGet("{action}")]
    public IActionResult GetTime() => Ok(DateTime.Now.ToString("HH:mm:ss"));
    
    [HttpGet("{action}")]
    public IActionResult GetDate() => Ok(DateTime.Now.ToString("yyyy-MM-dd"));
}
```


